import SwiftUI
struct ListsView: View {
    @State private var lists: [GroceryList] = []; @State private var showingNew = false; @State private var error: String?
    var body: some View { NavigationStack { List(lists) { list in NavigationLink(value: list) { VStack(alignment: .leading) { Text(list.name); if let total = list.itemCount { Text("\(total - (list.completedItemCount ?? 0)) remaining").font(.caption).foregroundStyle(.secondary) } } } }.navigationTitle("Family Lists").navigationDestination(for: GroceryList.self) { ListDetailView(list: $0) }.toolbar { Button { showingNew = true } label: { Image(systemName: "plus") } }.sheet(isPresented: $showingNew) { ListNameEditor(title: "New List") { name in await create(name) } }.task { await load() }.refreshable { await load() }.alert("Couldn’t load lists", isPresented: .constant(error != nil)) { Button("OK") { error = nil } } message: { Text(error ?? "") } } }
    private func load() async { do { struct Response: Decodable { let lists: [GroceryList] }; lists = try await APIClient.shared.request("/api/lists") } catch { self.error = "Please check your connection and try again." } }
    private func create(_ name: String) async { struct Body: Encodable { let name: String }; struct Response: Decodable { let list: GroceryList }; do { let response: Response = try await APIClient.shared.request("/api/lists", method: "POST", body: Body(name: name)); lists.append(response.list) } catch { error = "Couldn’t create the list." } }
}
struct ListNameEditor: View { let title: String; let save: (String) async -> Void; @Environment(\.dismiss) private var dismiss; @State private var name = ""; var body: some View { NavigationStack { Form { TextField("Name", text: $name) }.navigationTitle(title).toolbar { ToolbarItem(placement: .cancellationAction) { Button("Cancel") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("Save") { Task { await save(name); dismiss() } }.disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty) } } } } }
